<?php
declare(strict_types=1); require_once __DIR__.'/config.php';
function fetch_bricklink_pov(string $full,string $condition='N'):array{ $full=clean_set_num($full)??''; if($full==='')throw new RuntimeException('Set number required'); $condition=strtoupper($condition);if(!in_array($condition,['N','U'],true))$condition='N'; $base=$full;$seq=1;if(preg_match('/^(.*)-([0-9]+)$/',$full,$m)){$base=$m[1];$seq=(int)$m[2];}
$url='https://www.bricklink.com/catalogPOV.asp?'.http_build_query(['itemType'=>'S','itemNo'=>$base,'itemSeq'=>$seq,'itemQty'=>1,'breakType'=>'M','itemCondition'=>$condition,'incInstr'=>'Y','incBox'=>'Y']);
$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_TIMEOUT=>25,CURLOPT_USERAGENT=>'Mozilla/5.0 LEGO-Resale/'.APP_VERSION]);$html=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$err=curl_error($ch);curl_close($ch);if($html===false||$code<200||$code>=400)throw new RuntimeException("BrickLink lookup failed ($code) $err"); $text=preg_replace('/\\s+/u',' ',html_entity_decode(strip_tags((string)$html),ENT_QUOTES|ENT_HTML5,'UTF-8'));
$sold=$cur=null;$si=$sl=$ci=$cl=null; if(preg_match('/Average of last 6 months Sales:.*?US\\s*\\$\\s*([0-9,]+(?:\\.\\d{1,2})?)/i',$text,$m))$sold=(float)str_replace(',','',$m[1]); if(preg_match('/Current Items For Sale Average:.*?US\\s*\\$\\s*([0-9,]+(?:\\.\\d{1,2})?)/i',$text,$m))$cur=(float)str_replace(',','',$m[1]); if($sold===null&&$cur===null)throw new RuntimeException('POV values could not be parsed'); return ['ok'=>true,'setNumber'=>$full,'soldAverage'=>$sold,'currentAverage'=>$cur,'soldItems'=>$si,'soldLots'=>$sl,'currentItems'=>$ci,'currentLots'=>$cl,'sourceUrl'=>$url,'checkedAt'=>now_iso()]; }
if(basename($_SERVER['SCRIPT_FILENAME']??'')===basename(__FILE__)){require_role([ROLE_OWNER]);try{json_response(fetch_bricklink_pov((string)($_GET['set']??''),(string)($_GET['condition']??'N')));}catch(Throwable $e){json_response(['ok'=>false,'error'=>$e->getMessage()],502);}}
